// Primitive types
let num: number = 42;
let str: string = "hello";
let bool: boolean = true;
let nothing: null = null;
let undef: undefined = undefined;
let big: bigint = 42n;

// Special types
let anything: any = 42;     // opt out of type checking (avoid!)
let val: unknown = getInput(); // type-safe any — must narrow before use
function throwError(msg: string): never { throw new Error(msg); }  // never returns
function log(msg: string): void { console.log(msg); }  // no return value

// Arrays
let nums: number[] = [1, 2, 3];
let strs: Array<string> = ["a", "b"];
let ro: readonly number[] = [1, 2, 3];

// Tuples (fixed-length, typed positions)
let pair: [string, number] = ["Alice", 30];
let [name, age] = pair;  // destructuring
type Point3D = [x: number, y: number, z: number];

// Union types (one OR the other)
let id: string | number = "abc";
id = 42;   // also valid

// Intersection types (combines both)
type Admin = User & { admin: true };

// Literal types
type Direction = "north" | "south" | "east" | "west";
type StatusCode = 200 | 404 | 500;

// Utility types
Partial<User>        // all fields optional
Required<User>       // all fields required
Readonly<User>       // all fields readonly
Pick<User, "name" | "age">  // only these fields
Omit<User, "password">      // all except these
Record<string, number>      // dictionary
NonNullable<string | null>  // removes null/undefined
ReturnType<typeof fn>
Parameters<typeof fn>
