```typescript
// Interface — describe object shape
interface User {
    id: number;
    name: string;
    email?: string;       // optional
    readonly createdAt: Date;   // read-only
    greet(): string;
    update(data: Partial<User>): void;
}

// Interface extension
interface Admin extends User {
    role: "admin" | "superadmin";
    permissions: string[];
}

// Declaration merging (add to existing interface)
interface Window {
    myCustomProp: string;
}

// Callable interface
interface Formatter {
    (value: number, precision: number): string;
    defaultPrecision: number;
}

// Index signature (dictionary-like)
interface StringMap {
    [key: string]: string;
    length: number;   // known key with different type — error!
    // Must all be same type as index signature or assignable to it
}

// Type alias vs Interface:
// Use interface for object shapes (extensible)
// Use type for unions, intersections, mapped types
type ID = string | number;
type Nullable<T> = T | null;
type Callback<T> = (data: T) => void;

// Mapped types
type Optional<T> = { [K in keyof T]?: T[K] };
type Mutable<T> = { -readonly [K in keyof T]: T[K] };

// Conditional types
type IsArray<T> = T extends any[] ? true : false;
type Flatten<T> = T extends Array<infer Item> ? Item : T;
```

```typescript
// Generic functions
function identity<T>(arg: T): T { return arg; }
function first<T>(arr: T[]): T | undefined { return arr[0]; }
function zip<A, B>(a: A[], b: B[]): [A, B][] {
    return a.map((x, i) => [x, b[i]]);
}

// Constrained generics
function logLength<T extends { length: number }>(val: T): T {
    console.log(val.length);
    return val;
}

// keyof — access object property dynamically
function getProperty<T, K extends keyof T>(obj: T, key: K): T[K] {
    return obj[key];
}
const name = getProperty(user, "name");  // typed as string!

// Function overloads
function format(value: number): string;
function format(value: string): string;
function format(value: number | string): string {
    return typeof value === "number" ? value.toFixed(2) : value.trim();
}

// Type predicate (user-defined type guard)
function isString(val: unknown): val is string {
    return typeof val === "string";
}

const x: unknown = getInput();
if (isString(x)) {
    x.toUpperCase();  // TS knows x is string here
}

// Assertion function
function assertDefined<T>(val: T): asserts val is NonNullable<T> {
    if (val == null) throw new Error("Expected defined value");
}

// Higher-order
function compose<T>(...fns: Array<(x: T) => T>): (x: T) => T {
    return (x) => fns.reduceRight((acc, fn) => fn(acc), x);
}
