```typescript
class Animal {
    private name: string;       // private — only this class
    protected sound: string;    // protected — this + subclasses
    public readonly id: number; // public read-only
    #privateField = 42;         // ECMAScript private

    constructor(name: string, sound: string) {
        this.name = name;
        this.sound = sound;
        this.id = Math.random();
    }

    // Parameter property shorthand (declare + assign in constructor)
    // constructor(private name: string, public age: number) {}

    get displayName(): string { return this.name; }
    set displayName(val: string) { this.name = val; }

    speak(): string { return `${this.name} says ${this.sound}`; }
    static create(name: string): Animal { return new Animal(name, "..."); }
}

class Dog extends Animal {
    constructor(name: string, public breed: string) {
        super(name, "Woof");
    }
    override speak(): string { return super.speak() + "!"; }  // override
}

// Abstract class
abstract class Shape {
    abstract get area(): number;
    abstract get perimeter(): number;
    describe(): void { console.log(`Area=${this.area.toFixed(2)}`); }
}

class Circle extends Shape {
    constructor(private r: number) { super(); }
    get area() { return Math.PI * this.r ** 2; }
    get perimeter() { return 2 * Math.PI * this.r; }
}

// Generic class
class Pair<A, B> {
    constructor(public first: A, public second: B) {}
    swap(): Pair<B, A> { return new Pair(this.second, this.first); }
}

const p = new Pair("hello", 42);
p.first;   // string
p.second;  // number
p.swap()   // Pair<number, string>
```

```typescript
// typeof narrowing
function process(val: string | number) {
    if (typeof val === "string") {
        return val.toUpperCase();   // string here
    }
    return val.toFixed(2);          // number here
}

// instanceof narrowing
function handleError(err: unknown) {
    if (err instanceof TypeError) {
        console.log("Type error:", err.message);
    } else if (err instanceof Error) {
        console.log("Error:", err.message);
    } else {
        console.log("Unknown:", err);
    }
}

// in narrowing
interface Cat { meow(): void; }
interface Dog { bark(): void; }
function makeNoise(animal: Cat | Dog) {
    if ("meow" in animal) animal.meow();
    else animal.bark();
}

// Discriminated unions — best pattern for complex cases!
type Shape =
    | { kind: "circle"; radius: number }
    | { kind: "rect"; width: number; height: number };

function area(shape: Shape): number {
    switch (shape.kind) {
        case "circle": return Math.PI * shape.radius ** 2;
        case "rect":   return shape.width * shape.height;
    }  // TS knows all cases are handled!
}

// Exhaustiveness check
function assertNever(x: never): never {
    throw new Error("Unexpected: " + x);
}

// as const — infer literal types
const config = { host: "localhost", port: 8080 } as const;
// config.port is 8080 (literal type), not number

// Nullish patterns
const x = value ?? defaultValue;    // null/undefined → default
const len = str?.length ?? 0;       // optional chain + nullish
obj?.method?.();                     // safe method call
```

```typescript
// Conditional types
type IsArray<T> = T extends any[] ? true : false;
type ElementType<T> = T extends (infer E)[] ? E : never;
type Unpromise<T> = T extends Promise<infer R> ? R : T;
type RetType<T> = T extends (...args: any[]) => infer R ? R : never;

type T1 = Unpromise<Promise<string>>;  // string
type T2 = ElementType<number[]>;       // number

// Template literal types
type EventName = "click" | "focus" | "blur";
type Handler = `on${Capitalize<EventName>}`;  // "onClick" | "onFocus" | "onBlur"

type Getter<T extends string> = `get${Capitalize<T>}`;
type SetterOf<T> = {
    [K in keyof T as `set${Capitalize<string & K>}`]: (val: T[K]) => void;
};

// Mapped types
type Optional<T> = { [K in keyof T]?: T[K] };
type Mutable<T> = { -readonly [K in keyof T]: T[K] };  // remove readonly
type Stringify<T> = { [K in keyof T]: string };

// Getters generator
type Getters<T> = {
    [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K];
};

type UserGetters = Getters<User>;
// { getName: () => string; getAge: () => number; ... }

// infer in function types
type FirstParam<T> = T extends (first: infer F, ...rest: any[]) => any ? F : never;
type FP = FirstParam<(name: string, age: number) => void>;  // string

// Recursive types
type DeepPartial<T> = T extends object
    ? { [K in keyof T]?: DeepPartial<T[K]> }
    : T;
